no_effort, configured_none, low = _wire_effort_profiles(tmp_path / "profiles") server = CodexAppServer(tmp_path / "session", no_effort) fixtures = Path(__file__).parent / "fixtures" / "codex" / version schema = json.loads((fixtures / "ModelListResponse.json").read_text()) response = {"data": [server._model(p) for p in server.model_profiles], "nextCursor": None} jsonschema.Draft7Validator(schema).validate(response) # This is a source-derived picker projection, not execution of Rust/TUI. for model in response["data"]: choices = [option["reasoningEffort"] for option in model["supportedReasoningEfforts"]] choices = choices or [model["defaultReasoningEffort"]] for choice in choices: profile = server._profile_for_selection(model["model"], choice) assert server._effort_to_wire(profile, profile.reasoning_effort) == choice assert server._profile_for_selection("unconfigured", "none").path == no_effort assert server._profile_for_selection("unconfigured", "none").reasoning_effort is None assert server._profile_for_selection("configured-none", "none").path == configured_none assert server._profile_for_selection("configured-none", "none").reasoning_effort == "none" assert server._profile_for_selection("configured-none", "low").path == low assert next(m for m in response["data"] if m["id"] == "unconfigured")[ "supportedReasoningEfforts"] == [] with pytest.raises(ValueError, match="unknown RPNH reasoning effort"): server._profile_for_selection("unconfigured", "medium") with pytest.raises(ValueError, match="unknown RPNH provider/model"): server._profile_for_selection("unknown", "none") > assert '"none"' in (fixtures / "ReasoningEffort.ts").read_text() E assert '"none"' in '// GENERATED CODE! DO NOT MODIFY BY HAND!

